SET    SUBSIDIARY_CODE                        = NVL(#{LGVHR_PROJECT_SESSION.subsidiaryCode}, 'LGDVN')
     , grade_name                             = #{gradeName}
     , allowance_id           			      = #{allowanceId, jdbcType=NUMERIC}
